#!/bin/bash
#
# Generate small subset mzML files and FASTA databases for testing
#
# Usage: ./generate_test_subsets.sh
#
# This script uses msconvert from ProteoWizard to create small test subsets.
# Reference: https://proteowizard.sourceforge.io/tools/msconvert.html
#
# NOTE: Module inputs (module_inputs/) are NOT generated by this script.
# They are produced by running upstream pipeline stages (MSFragger, Percolator,
# Philosopher, etc.) and must be updated manually when upstream tools change.

set -euo pipefail

# Configuration
MSCONVERT_IMAGE="proteowizard/pwiz-skyline-i-agree-to-the-vendor-licenses:skyline_daily_26.0.9.004-7b2495b"
OUTPUT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
TEMP_DIR="${OUTPUT_DIR}/tmp"
SPECTRA_DIR="${OUTPUT_DIR}/spectra"
DB_DIR="${OUTPUT_DIR}/databases"

# Scan range for TMT data (middle of gradient where peptides elute)
# Two subsets created for multi-sample channel testing
TMT_SCAN_START_1=4000
TMT_SCAN_END_1=4500
TMT_SCAN_START_2=4500
TMT_SCAN_END_2=5000

# Scan ranges for DDA data (two subsets for multi-sample testing)
DDA_SCAN_START_1=0
DDA_SCAN_END_1=499
DDA_SCAN_START_2=500
DDA_SCAN_END_2=999

# Scan limit for DIA data (2500 scans needed for peptide identification)
DIA_SCAN_LIMIT=2500

echo "=== FragPipe Test Data Generator ==="
echo "Output directory: ${OUTPUT_DIR}"
echo "TMT scan ranges: ${TMT_SCAN_START_1}-${TMT_SCAN_END_1}, ${TMT_SCAN_START_2}-${TMT_SCAN_END_2}"
echo "DDA scan ranges: ${DDA_SCAN_START_1}-${DDA_SCAN_END_1}, ${DDA_SCAN_START_2}-${DDA_SCAN_END_2}"
echo "DIA scan limit: ${DIA_SCAN_LIMIT}"
echo ""

# Create directories
mkdir -p "${TEMP_DIR}" "${SPECTRA_DIR}" "${DB_DIR}"

#------------------------------------------------------------------------------
# TMT Dataset: PRIDE PXD000001 (Erwinia TMT6)
#------------------------------------------------------------------------------
generate_tmt_subset() {
    echo "=== Generating TMT subsets from PRIDE PXD000001 ==="

    local RAW_URL="https://ftp.pride.ebi.ac.uk/pride/data/archive/2012/03/PXD000001/TMT_Erwinia_1uLSike_Top10HCD_isol2_45stepped_60min_01.raw"
    local FASTA_URL="https://ftp.pride.ebi.ac.uk/pride/data/archive/2012/03/PXD000001/erwinia_carotovora.fasta"
    local RAW_FILE="${TEMP_DIR}/tmt_erwinia.raw"
    local OUTPUT_FASTA="${DB_DIR}/erwinia_carotovora.fasta"

    # Download RAW file
    if [[ ! -f "${RAW_FILE}" ]]; then
        echo "Downloading TMT RAW file..."
        curl -L -o "${RAW_FILE}" "${RAW_URL}"
    else
        echo "TMT RAW file already exists, skipping download"
    fi

    # Download FASTA file
    if [[ ! -f "${OUTPUT_FASTA}" ]]; then
        echo "Downloading FASTA file..."
        curl -L -o "${OUTPUT_FASTA}" "${FASTA_URL}"
    else
        echo "FASTA file already exists, skipping download"
    fi

    # Convert and subset using msconvert - first subset
    echo "Converting TMT RAW to mzML subset 1 (scans ${TMT_SCAN_START_1}-${TMT_SCAN_END_1})..."
    docker run --rm \
        -v "${TEMP_DIR}:/data:ro" \
        -v "${SPECTRA_DIR}:/output" \
        "${MSCONVERT_IMAGE}" \
        wine msconvert \
        "/data/tmt_erwinia.raw" \
        --outdir /output \
        --outfile tmt_erwinia_subset.mzML \
        --mzML \
        --filter "scanNumber [${TMT_SCAN_START_1},${TMT_SCAN_END_1}]" \
        --filter "peakPicking true 1-" \
        --zlib

    # Convert and subset using msconvert - second subset
    echo "Converting TMT RAW to mzML subset 2 (scans ${TMT_SCAN_START_2}-${TMT_SCAN_END_2})..."
    docker run --rm \
        -v "${TEMP_DIR}:/data:ro" \
        -v "${SPECTRA_DIR}:/output" \
        "${MSCONVERT_IMAGE}" \
        wine msconvert \
        "/data/tmt_erwinia.raw" \
        --outdir /output \
        --outfile tmt_erwinia_subset_2.mzML \
        --mzML \
        --filter "scanNumber [${TMT_SCAN_START_2},${TMT_SCAN_END_2}]" \
        --filter "peakPicking true 1-" \
        --zlib

    echo "TMT subsets generated:"
    ls -lh "${SPECTRA_DIR}"/tmt_erwinia_subset*.mzML
}

#------------------------------------------------------------------------------
# DDA Dataset: Zenodo SILAC HEK
#------------------------------------------------------------------------------
generate_dda_subset() {
    echo ""
    echo "=== Generating DDA subsets from Zenodo SILAC ==="

    local MZML_URL="https://zenodo.org/records/1051552/files/HEK_SILAC-K6R6_ST905_part.mzml?download=1"
    local MZML_FILE="${TEMP_DIR}/dda_silac.mzML"

    # Download mzML file
    if [[ ! -f "${MZML_FILE}" ]]; then
        echo "Downloading DDA mzML file..."
        curl -L -o "${MZML_FILE}" "${MZML_URL}"
    else
        echo "DDA mzML file already exists, skipping download"
    fi

    # Subset using msconvert - first subset
    echo "Creating DDA mzML subset 1 (scans ${DDA_SCAN_START_1}-${DDA_SCAN_END_1})..."
    docker run --rm \
        -v "${TEMP_DIR}:/data:ro" \
        -v "${SPECTRA_DIR}:/output" \
        "${MSCONVERT_IMAGE}" \
        wine msconvert \
        "/data/dda_silac.mzML" \
        --outdir /output \
        --outfile dda_silac_subset.mzML \
        --mzML \
        --filter "index [${DDA_SCAN_START_1},${DDA_SCAN_END_1}]" \
        --zlib

    # Subset using msconvert - second subset
    echo "Creating DDA mzML subset 2 (scans ${DDA_SCAN_START_2}-${DDA_SCAN_END_2})..."
    docker run --rm \
        -v "${TEMP_DIR}:/data:ro" \
        -v "${SPECTRA_DIR}:/output" \
        "${MSCONVERT_IMAGE}" \
        wine msconvert \
        "/data/dda_silac.mzML" \
        --outdir /output \
        --outfile dda_silac_subset_2.mzML \
        --mzML \
        --filter "index [${DDA_SCAN_START_2},${DDA_SCAN_END_2}]" \
        --zlib

    echo "DDA subsets generated:"
    ls -lh "${SPECTRA_DIR}"/dda_silac_subset*.mzML
}

#------------------------------------------------------------------------------
# DIA Dataset: CPTAC CCRCC (Human Kidney Cancer, DIA)
#------------------------------------------------------------------------------
generate_dia_subset() {
    echo ""
    echo "=== Generating DIA subset from CPTAC CCRCC ==="

    # Dropbox link containing CPTAC CCRCC DIA data
    local ZIP_URL="https://www.dropbox.com/scl/fo/zpd2rxlh6uzg0ewyhqtir/h?rlkey=25fgtzhckw9q8adu12kd7mjnp&dl=1"
    local ZIP_FILE="${TEMP_DIR}/dia_cptac.zip"
    local MZML_FILE="${TEMP_DIR}/CPTAC_CCRCC_W_JHU_20190112_LUMOS_C3L-01882_T.mzML"

    # Download and extract if needed
    if [[ ! -f "${MZML_FILE}" ]]; then
        echo "Downloading DIA dataset from Dropbox..."
        curl -L -o "${ZIP_FILE}" "${ZIP_URL}"
        echo "Extracting DIA files..."
        unzip -o "${ZIP_FILE}" "CPTAC_CCRCC_W_JHU_20190112_LUMOS_C3L-01882_T.mzML" -d "${TEMP_DIR}/"
        rm -f "${ZIP_FILE}"
    else
        echo "DIA mzML file already exists, skipping download"
    fi

    # Subset mzML using msconvert
    echo "Creating DIA mzML subset (first ${DIA_SCAN_LIMIT} scans)..."
    docker run --rm \
        -v "${TEMP_DIR}:/data:ro" \
        -v "${SPECTRA_DIR}:/output" \
        "${MSCONVERT_IMAGE}" \
        wine msconvert \
        "/data/CPTAC_CCRCC_W_JHU_20190112_LUMOS_C3L-01882_T.mzML" \
        --outdir /output \
        --outfile dia_cptac_subset.mzML \
        --mzML \
        --filter "index [0,$((DIA_SCAN_LIMIT - 1))]" \
        --zlib

    echo "DIA subset generated:"
    ls -lh "${SPECTRA_DIR}/dia_cptac_subset.mzML"
}

#------------------------------------------------------------------------------
# Download FASTA databases from UniProt
#------------------------------------------------------------------------------
download_databases() {
    echo ""
    echo "=== Downloading FASTA databases ==="

    # Human SwissProt subset (500 reviewed proteins)
    local HUMAN_FASTA="${DB_DIR}/human_sp_subset.fasta"
    local HUMAN_URL="https://rest.uniprot.org/uniprotkb/stream?format=fasta&query=%28%28proteome%3AUP000005640%29%20AND%20%28reviewed%3Atrue%29%29&size=500"

    if [[ ! -f "${HUMAN_FASTA}" ]]; then
        echo "Downloading human SwissProt subset (500 proteins)..."
        curl -L -o "${HUMAN_FASTA}" "${HUMAN_URL}"
    else
        echo "Human FASTA subset already exists, skipping download"
    fi
    ls -lh "${HUMAN_FASTA}"

    # Erwinia UniProt proteome (with OS=/OX= headers for metaproteomics)
    local ERWINIA_UP_FASTA="${DB_DIR}/erwinia_uniprot.fasta"
    local ERWINIA_UP_URL="https://rest.uniprot.org/uniprotkb/stream?format=fasta&query=%28%28proteome%3AUP000000745%29%20AND%20%28reviewed%3Atrue%29%29"

    if [[ ! -f "${ERWINIA_UP_FASTA}" ]]; then
        echo "Downloading Erwinia UniProt proteome..."
        curl -L -o "${ERWINIA_UP_FASTA}" "${ERWINIA_UP_URL}"
    else
        echo "Erwinia UniProt FASTA already exists, skipping download"
    fi
    ls -lh "${ERWINIA_UP_FASTA}"
}

#------------------------------------------------------------------------------
# Main
#------------------------------------------------------------------------------
main() {
    echo "Starting test data generation..."
    echo ""

    # Pull docker image first
    echo "Pulling msconvert Docker image..."
    docker pull "${MSCONVERT_IMAGE}"
    echo ""

    generate_tmt_subset
    generate_dda_subset
    generate_dia_subset
    download_databases

    echo ""
    echo "=== Summary ==="
    echo "Spectra:"
    ls -lh "${SPECTRA_DIR}"/*.mzML
    echo ""
    echo "Databases:"
    ls -lh "${DB_DIR}"/*.fasta

    echo ""
    echo "Cleaning up temp directory..."
    # Uncomment to auto-cleanup:
    # rm -rf "${TEMP_DIR}"
    echo "Temp files kept in: ${TEMP_DIR}"

    echo ""
    echo "Done! Test data ready in: ${OUTPUT_DIR}"
    echo ""
    echo "NOTE: module_inputs/ files are not generated by this script."
    echo "They must be produced by running upstream pipeline stages."
}

main "$@"
